contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint _am, uint depositAmount, uint minSumVal) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(other != address(0));
        require(other != address(this));
        require(address(this).balance >= depositAmount);

        c.SetMinSum(minSumVal); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint otherBefore = c.balances(other); if (__ESBMC_reverted()) return;
        uint cBalanceBefore = address(c).balance;

        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint otherAfter = c.balances(other); if (__ESBMC_reverted()) return;
        uint cBalanceAfter = address(c).balance;

        bool eligible = balBefore >= minSumVal && balBefore >= _am;

        assert(
            (!eligible && balAfter == balBefore && otherAfter == otherBefore && cBalanceAfter == cBalanceBefore)
            || (eligible && !reverted && balAfter + _am == balBefore && otherAfter == otherBefore && cBalanceAfter == cBalanceBefore - _am)
            || (eligible && reverted && balAfter == balBefore && otherAfter == otherBefore)
        );
    }

    receive() external payable {}
}

